INSERT INTO `series` (`id_serie`, `tituloSerie`, `titulo_originalSerie`, `sinopsisSerie`, `anio_lanzamientoSerie`, `temporadasSerie`, `actoresSerie`, `episodiosSerie`, `generoSerie`, `idiomaSerie`, `posterSerie`, `calificacionSerie`, `trailerSerie`) VALUES
	(86, 'Bleach', 'BLEACH', 'La serie narra las aventuras de Ichigo Kurosaki, un adolescente que tiene la facultad de interactuar con los espíritus. Una noche, Ichigo se encuentra con una shinigami —personificación japonesa del Dios de la muerte— llamada Rukia Kuchiki, quien se sorprende que pueda verla. Sin embargo, su conversación es interrumpida por la aparición de un hollow, un espíritu maligno. Después de que Rukia fuera gravemente herida al tratar de proteger a Ichigo, esta intenta traspasarle parte de sus poderes a Ichigo para que pueda enfrentarse al hollow en igualdad de condiciones. No obstante, Ichigo sin darse cuenta los absorbe casi por completo y logra vencer con facilidad al espíritu.', 2004, 2, '[{"nombre": "Masakazu Morita", "personaje": "Ichigo Kurosaki (voice)", "foto": "https://image.tmdb.org/t/p/w200/2INsHYbx9gEhhzXPHdqBDdvHjFt.jpg"}, {"nombre": "Fumiko Orikasa", "personaje": "Rukia Kuchiki (voice)", "foto": "https://image.tmdb.org/t/p/w200/f5d1J13fksa1hK8u7AS95aO8b9.jpg"}, {"nombre": "Hiroki Yasumoto", "personaje": "Yasutora Sado (voice)", "foto": "https://image.tmdb.org/t/p/w200/vNIGLl0wFmdhdnulMssQ1qyNeBs.jpg"}]', '[{"id": 1, "numero": 1, "titulo": "Bleach", "episodios": [{"numero": 1, "titulo": "El día que me convertí en Shinigami", "duracion": "23 min"}, {"numero": 2, "titulo": "Trabajo de Shinigami", "duracion": "23 min"}, {"numero": 3, "titulo": "Deseo del hermano mayor, deseo de la hermana pequeña", "duracion": "23 min"}, {"numero": 4, "titulo": "Periquito maldito", "duracion": "23 min"}, {"numero": 5, "titulo": "¡Vence al enemigo invisible!", "duracion": "23 min"}, {"numero": 6, "titulo": "¡Lucha hasta la muerte! Ichigo Vs. Ichigo", "duracion": "23 min"}, {"numero": 7, "titulo": "¡Saludos de parte del oso de peluche!", "duracion": "23 min"}, {"numero": 8, "titulo": "17 de junio, memorias en la lluvia", "duracion": "23 min"}, {"numero": 9, "titulo": "Enemigo invencible", "duracion": "23 min"}, {"numero": 10, "titulo": "Asalto durante la vi